/*
 * Placing an order.
 *
 * The checkout endpoint answers in JSON because that is what the mobile app
 * and the partner integrations consume. The basket page posts to the same
 * endpoint and shows the confirmation where you are standing, rather than
 * navigating away to it.
 */
(function () {
  "use strict";
  var form = document.getElementById("checkout");
  var panel = document.getElementById("confirmation");
  if (!form || !panel) return;

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    var body = {};
    new FormData(form).forEach(function (v, k) { if (v !== "") body[k] = v; });

    fetch("/checkout", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    })
      .then(function (r) { return r.json().then(function (j) { return { ok: r.ok, j: j }; }); })
      .then(function (res) {
        panel.hidden = false;
        panel.className = "alert" + (res.ok ? " ok" : "");
        panel.textContent = res.ok
          ? Object.keys(res.j).map(function (k) { return k + ": " + res.j[k]; }).join("\n")
          : (res.j.error || "That did not go through.");
      })
      .catch(function () {
        panel.hidden = false;
        panel.className = "alert";
        panel.textContent = "That did not go through. Try again.";
      });
  });
})();

